 meta=json.loads((P/'metadata'/(label+'.result-summary.json')).read_text());source=P/'sources'/(label+'.png');im=Image.open(source);rgba=np.array(im);a=rgba[:,:,3]
 assert im.mode=='RGBA' and sha(source)==sha(pathlib.Path(meta['nativeOriginal']))
