 geo[key]={'recommendStandingSourceHeight':statistics.median(heights),'nativeUprightHeights':heights,'observedUprightIndices':upright,'measuredLayouts':str(layout),'basis':'Measured upright helmet-to-boot native alpha component height (no overhead weapon and no crouch). Same body scale for all poses within a sheet. Canvas crop/contour metadata only; PNG pixels unchanged.'}
