 alpha_review.append({'key':key,'sha256':sha(source),'dimensions':im.size,'alphaExtrema':[int(a.min()),int(a.max())],'opaqueEdgePixels48':edges,'separatedComponents8':12,'alphaZeroPixels':int((a==0).sum()),'alphaReviewStatus':'passed','visuallyViewedFullNativeSheet':True,'reviewedFacing':-1 if key.endswith('left') else 1,'all12FiguresIndependentDirection':True,'foreignFramesWithCanvasStencil':draft.get('foreign_body_frames',[]),'limits':'Native alpha antialias may have isolated pixels below alpha8. Inspector contour excludes neighbouring bodies when a padded crop overlaps; native image bytes are not modified.'})
