  groups[name]={'action':action,'frame':1,'sourcePoseIndex':index,'file':'assets/combat-sprites/core__fury/'+key+'-v1.png','source':f['source'],'nativeOriginal':f['nativeOriginal'],'sha256':f['sha256'],'point':point,'pointRGBA':rgba,'note':'Visible open end interior of original-style flamethrower muzzle, not hand, backpack or imaginary orb. Shoot/super share same native muzzle. Floor deployment mark documents real nozzle; engine floor trap collision placement remains root-owned and must not be silently changed.'}
