prop=P/'sources/FIRE_JETS_01.png';prop_meta=json.loads((P/'metadata/FIRE_JETS_01.result-summary.json').read_text());assert prop_meta['significantComponentCount']==3 and not any(prop_meta['opaqueEdgePixels'])
