 x0,y0,x1,y1=cell['bbox'];prop_geometry['views'].append({'index':cell['index'],'bbox':cell['bbox'],'frame':cell['frame'],'facing':1,'emissionSide':'left','nativeDirection':'left-to-right','displayWidthRecommendation':96,'displayHeightRecommendation':'Preserve native aspect ratio, do not stretch to a circular hitbox.'})
